import{_ as o,l as n,o as e,c as l,v as i,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"多臂老虎机与 UCB","description":"","frontmatter":{"title":"多臂老虎机与 UCB","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bandit-ucb.md","filePath":"cs/bandit-ucb.md","lastUpdated":1789023840000}'),h={name:"cs/bandit-ucb.md"};function b(u,a,_,m,B,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="多臂老虎机与-ucb" tabindex="-1">多臂老虎机与 UCB <a class="header-anchor" href="#多臂老虎机与-ucb" aria-label="Permalink to &quot;多臂老虎机与 UCB&quot;">​</a></h1><div class="epigraph"><p>探索未知臂与利用当前最好之间折中；UCB 用均值加 $\\sqrt{(\\log t)/n_i}$ 上置信界，遗憾 $O(\\log T)$。</p><footer>—— 据 Lai and Robbins, 1985；Auer, Cesa-Bianchi and Fischer, Finite-time Analysis of the Multiarmed Bandit, 2002 整理</footer></div><p>上一课<a href="/cs/secretary-problem">秘书问题</a>一次性选择。多臂：重复拉 \\(K\\) 臂，\\(T\\) 轮，奖励随机。缺口是遗憾（regret）与 UCB。不重写 \\(1/e\\)。本序列「不确定输入」在此结束。不写神经网络策略。下一序列近似算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>臂 \\(i\\) 均值 \\(\\mu_i\\)，\\(\\mu^*=\\max\\mu_i\\)。遗憾 \\(R_T=T\\mu^*-\\sum\\) 收益。贪心只利用会锁死次优。\\(\\varepsilon\\)-贪心：以 \\(\\varepsilon\\) 探索。UCB1：\\(i\\) 的指标 \\(\\bar x_i+\\sqrt{2\\ln t/n_i}\\)，拉最大者。次优臂拉 \\(O(\\log T)\\) 次，遗憾 \\(O(\\log T)\\)。</p><p>缺口是置信界探索，不是 MDP 全动态规划。</p><h3 id="不是广告拍卖课" tabindex="-1">不是广告拍卖课 <a class="header-anchor" href="#不是广告拍卖课" aria-label="Permalink to &quot;不是广告拍卖课&quot;">​</a></h3><p>同一公式可出现在推荐，本课算法遗憾。不写限价。</p><p><span class="marginnote">Lai–Robbins 渐近下界。Auer 等 2002 UCB1 有限时间。后课顶点覆盖 2-近似换离线近似。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每臂维护次数与和。每轮 UCB 选臂，观察奖励更新。\\(\\varepsilon\\) 可递减。下界：Lai–Robbins 对数遗憾必要（一定条件下）。</p>',11)),(e(),s(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARM%5B%22K%20%E8%87%82%22%5D%20--%3E%20UCB%5B%22%E5%9D%87%E5%80%BC%20%2B%20%E7%BD%AE%E4%BF%A1%22%5D%0A%20%20UCB%20--%3E%20PULL%5B%22%E6%8B%89%E8%87%82%E8%A7%82%E5%AF%9F%22%5D%0A%20%20PULL%20--%3E%20REG%5B%22%E9%81%97%E6%86%BE%20O(log%20T)%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>分布有界假设（Hoeffding）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>欠拉的臂置信宽，指标大，被迫探索。拉够则置信缩，利用真最好。与秘书：秘书不能回头拉；bandit 可反复。与混合时间：这里 i.i.d. 奖励，不是图游走。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写对抗 bandit（Exp3）、不写上下文 bandit 全文。后课默认：随机 bandit 用 UCB，遗憾对数。下一课顶点覆盖 2-近似。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>遗憾权衡探索/利用。</li><li>UCB 上置信界，\\(O(\\log T)\\)。</li><li>贪心可锁死。</li><li>出处：Lai and Robbins, 1985；Auer, Cesa-Bianchi and Fischer, 2002。</li></ul>',7))])}const E=o(h,[["render",b]]);export{C as __pageData,E as default};
